REPO_FOLDERS = omni.repo.man.get_repo_paths()
SCRIPT_ROOT = os.path.dirname(os.path.realpath(__file__))
REPO_ROOT = REPO_FOLDERS["root"]

logger = logging.getLogger(os.path.basename(__file__))

KIT_ARCHIVE_PATTERN = "_builtpackages/omniverse-kit@*{config}.7z"

# Kit SDK build pipeline - each stage depends on the previous one
KIT_SDK_PIPELINE = ["kit-sdk", "kit-kernel", "kit-kernel-public", "kit-kernel-whl"]

PRODUCTS = KIT_SDK_PIPELINE + ["coreapi"]

APPS_TO_INCLUDE_IN_KIT_SDK = {
    "omni.app.dev",
    "omni.app.editor.base",
    "omni.app.empty",
    "omni.app.full",
    "omni.app.hydra",
    "omni.app.mini-hydra",
    "omni.app.mini",
    "omni.app.viewport",
    "omni.app.dev.xr.ipad",
    "omni.app.dev.xr.avp",
    "omni.app.dev.nvcf"
}


@lru_cache()
def get_repo_exec():
    host_platform = omni.repo.man.get_host_platform()
    return f"{REPO_ROOT}/repo.bat" if host_platform == "windows-x86_64" else f"{REPO_ROOT}/repo.sh"


def create_package(package_name, root, options, stage_only = False) -> str:
    """Stage and create package using repo_package tool.

    It first prepares all the content in permnanent folder (staging) and then packages into an archive.
    That staging path is returned and can be used to create another package.
    """
    command = [get_repo_exec(), "package", "-m", package_name, "-c", options.config, "--root", root]
    stage_path = f"{REPO_ROOT}/_builtpackages/{package_name}-{options.config}"
    if os.path.exists(stage_path):
        clean_folders([stage_path])

    if platform.system() == "Darwin":
        command.extend(["--platform-target", "macos-universal"])

    # Stage package in specified path and keep it:
    command.extend(["--temp-dir", stage_path])
    command.extend([f"--/repo_package/packages/{package_name}/keeptemp=1"])
    # If we are only staging, skip packaging (no archive will be created):
    if stage_only:
        command.extend(["--stage-only"])
    # Forward no-strip option if specified
    if options.no_strip:
        command.extend(["--no-strip"])

    action = "Staging" if stage_only else "Packaging"
    print(f"    {action} {package_name}... Command: " + process_args_to_cmd(command))
    omni.repo.man.run_process(command, exit_on_error=True)
    print(f"    Completed {action.lower()} {package_name} at {stage_path}")

    return stage_path

def resolve_path(path, options):
    return omni.repo.man.resolve_tokens(path, extra_tokens = { "config": options.config})

def remove_unnecessary_files_from_kit_sdk(staged_root):
    # Normally we specify files to be included/excluded in "package.toml".
    # It works well for a big patterns, like excluding a whole dir. But if we specify individual files in "package.toml", it
    # would affect performance of the packaging process. Ideally, we would restructure files in the repo so that those
    # that should be packaged are separated in other dir. But it is tricky to do for all "apps" that are in the same place.
    # So just specially for apps we do it here programmatically.
    # We operate on the staged package (e.g. _builtpackages/kit-sdk-release) only, never on _build/.../apps/, so we
    # never delete through symlinks into source. In the staged package, .kit files are in apps/, shell scripts at root.
    # The dangerous case is if apps/ itself is a symlink: then deleting a "file" in apps/ would delete from the
    # source dir. Removing symlink *files* is fine (only removes the link). We check that apps/ is not a symlink.

    def remove_if_exists(path):
        if os.path.exists(path):
            print(f"Removing: {path}")
            os.remove(path)

    apps_dir = os.path.join(staged_root, "apps")
    if not os.path.isdir(apps_dir):
        return

    if os.path.islink(apps_dir):
        raise RuntimeError(
            f"Staged apps dir is a symlink: {apps_dir}. "
            "Refusing to remove files; deleting would affect the link target (source)."
        )

    for app in glob.glob(os.path.join(apps_dir, "*")):
        stem = os.path.splitext(os.path.basename(app))[0]
        if stem not in APPS_TO_INCLUDE_IN_KIT_SDK:
            remove_if_exists(app)
            remove_if_exists(os.path.join(staged_root, f"{stem}.bat"))
            remove_if_exists(os.path.join(staged_root, f"{stem}.sh"))


def adjust_kit_kernel_package_for_public_version(root, options):
    # Simplify packman config to only include cloudfront remote for downloading packages:
    packman_config_path = resolve_path(root + "/dev/tools/packman/config.packman.xml", options)
    packman_config = """
<config remotes="cloudfront">
    <remote2 name="cloudfront">
        <transport actions="download" protocol="https" packageLocation="d4i3qtqj3r0z5.cloudfront.net/${name}@${version}" />
    </remote2>
</config>
"""
    with open(packman_config_path, "w") as f:
        f.write(packman_config)

    # Change a few things in the kit-core.json file to prepare to build public version:
    kit_core_json = resolve_path(root + "/kernel/config/kit-core.json", options)
    with open(kit_core_json, "r") as f:
        kit_core_data = json.load(f)

    # Set external build to true in kit-core.json:
    kit_core_data["privacy"]["externalBuild"] = True

    # Leave only public registries:
    registries = kit_core_data["exts"]["omni.kit.registry.nucleus"]["registries"]
    registries = [r for r in registries if r["name"].startswith("kit/prod")]
    kit_core_data["exts"]["omni.kit.registry.nucleus"]["registries"] = registries

    with open(kit_core_json, "w") as f:
        json.dump(kit_core_data, f, indent=4)


def build_kit_sdk_packages(root, options):
    """
    Build kit-sdk packages in a pipeline: kit-sdk -> kit-kernel -> kit-kernel-public -> kit-kernel-whl
    Each stage depends on the previous one. If you request a later stage, all earlier stages are built automatically.
    """
    # Find the furthest product requested in the pipeline
    furthest_product = None
    for product in reversed(KIT_SDK_PIPELINE):
        if product in options.product:
            furthest_product = product
            break

    # If no kit-sdk products were requested, nothing to do
    if furthest_product is None:
        return

    # Show the build plan
    furthest_index = KIT_SDK_PIPELINE.index(furthest_product)
    products_to_build = KIT_SDK_PIPELINE[:furthest_index + 1]
    print(f"\n{'='*80}")
    print(f"Building Kit SDK pipeline: {' -> '.join(products_to_build)}")
    print(f"Final product: {furthest_product}")
    print(f"Mode: {'stage-only' if options.stage_only else 'stage + archive'}")
    print(f"{'='*80}\n")

    # Now build all stages up to and including the requested one
    # Stage: kit-sdk (base package)
    print(f"[1/{len(products_to_build)}] Building kit-sdk (base package)...")
    kit_sdk_root = create_package("kit-sdk", root=root, options=options, stage_only=options.stage_only)
    remove_unnecessary_files_from_kit_sdk(kit_sdk_root)
    print(f"    [OK] kit-sdk completed\n")

    if furthest_product == "kit-sdk":
        return

    # Stage: kit-kernel (smaller package built from kit-sdk)
    print(f"[2/{len(products_to_build)}] Building kit-kernel (smaller package)...")
    kit_kernel_root = create_package("kit-kernel", root=kit_sdk_root, options=options, stage_only=options.stage_only)
    print(f"    [OK] kit-kernel completed\n")

    if furthest_product == "kit-kernel":
        return

    # Stage: kit-kernel-public (public version with modified configs)
    print(f"[3/{len(products_to_build)}] Building kit-kernel-public (public version)...")
    adjust_kit_kernel_package_for_public_version(kit_kernel_root, options)
    kit_kernel_public_root = create_package("kit-kernel-public", root=kit_kernel_root, options=options, stage_only=options.stage_only)
    print(f"    [OK] kit-kernel-public completed\n")

    if furthest_product == "kit-kernel-public":
        return

    # Stage: kit-kernel-whl (pip/wheel packages, only for release builds)
    print(f"[4/{len(products_to_build)}] Building kit-kernel-whl (pip/wheel packages)...")
    if options.config == "release":
        command = [get_repo_exec(), "python_package", "--source-root", kit_kernel_public_root]
        print(f"    Command: {process_args_to_cmd(command)}")
        omni.repo.man.run_process(command, exit_on_error=True)
        print(f"    [OK] kit-kernel-whl completed")
        print(f"    Generated wheels:")
        print(f"      - omniverse_kit-*.whl (main kernel package)")
        print(f"      - generic_model_output-*.whl (sensor utility)")
        print(f"      - sensor_checker-*.whl (sensor utility)\n")
        print(f"##teamcity[publishArtifacts '_builtpackages/*.whl']")
    else:
        print(f"    [!] Skipping whl build (only available for release config, current: {options.config})\n")


def build_coreapi_packages(root, options):
    # Package coreapi using this package as a root:
    coreapi_root = create_package("coreapi", root=root, options=options, stage_only=True)

    with omni.repo.man.change_cwd(REPO_ROOT):
        # Download extra extensions from outside of kit repo
        cmd = [
            f"{coreapi_root}/omni.app.coreapi-alpha_headless.sh",
            "--ext-precache-mode",
            "--/app/extensions/registryEnabled=1",
            f"--/app/extensions/registryCacheFull={coreapi_root}/extscache",
            "--/app/extensions/parallelPullEnabled=1",
            "--/exts/omni.kit.registry.nucleus/cacheCreateLinks=0",
            "--/structuredLog/enableJsonStdout=false", # leaving this enabled makes reading errors hard
        ]
        print(f"Downloading (precaching) extra extensions... Command: " + process_args_to_cmd(cmd))
        omni.repo.man.run_process(cmd, exit_on_error=True)

        # Remove unused extensions using kit extension manager API (remove all disabled extensions):
        cmd = [
            f"{coreapi_root}/omni.app.coreapi-alpha_headless.sh",
            "--disable-ext-startup",
            "--exec",
            "./source/docker/coreapi-alpha-service/remove_unused_extensions.py",
        ]
        print(f"Trimming unused extensions... Command: " + process_args_to_cmd(cmd))
        omni.repo.man.run_process(cmd, exit_on_error=True)

        coreapi_root = os.path.relpath(coreapi_root)
        data_path = os.path.relpath(f"{root}/data")

        # Build docker image:
        uid = os.getuid()
        uid = uid if uid != 0 else 1001
        dockerfile_path = f"{REPO_ROOT}/source/docker/coreapi-alpha-service/Dockerfile"
        cmd = [
            "docker",
            "build",
            "-t",
            f"{options.image_tag}",
            "--build-arg",
            f"UID={uid}",
            "--build-arg",
            f"COREAPI_PACKAGE_PATH={coreapi_root}",
            "--build-arg",
            f"KIT_DATA_PATH={data_path}",
            "-f",
            dockerfile_path,
            ".",
        ]
        print(f"Building docker image... Command: " + process_args_to_cmd(cmd))
        omni.repo.man.run_process(cmd, exit_on_error=True)



def main():
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "-c", "--config", dest="config", required=False, default="release", help="Config target. (default: %(default)s)"
    )
    parser.add_argument("-x", "--clean", dest="clean", required=False, action="store_true")
    parser.add_argument(
        "-p",
        "--platform-target",
        dest="platform_target",
        default=omni.repo.man.get_host_platform(),
        required=False,
        help="Platform. (default: %(default)s)",
    )
    parser.add_argument(
        "--from-package",
        dest="from_package",
        default=False,
        action="store_true",
        help=f"Use package from '{KIT_ARCHIVE_PATTERN}' instead of a root folder.",
    )
    parser.add_argument(
        "--product",
        dest="product",
        default=KIT_SDK_PIPELINE,
        nargs="+",
        choices=PRODUCTS,
        help="Product name(s). (default: %(default)s)",
    )
    parser.add_argument(
        "--image-tag", dest="image_tag", required=False, help="Image tag to use for coreapi docker image."
    )
    parser.add_argument(
        "--no-strip",
        dest="no_strip",
        default=False,
        action="store_true",
        help=f"Disable stripping of debug symbols when preparing the package. USE FOR DEVELOPMENT PURPOSES ONLY.",
    )
    parser.add_argument(
        "--stage-only",
        dest="stage_only",
        default=False,
        action="store_true",
        help="Only stage packages without creating archives. Useful for development and debugging.",
    )

    options = parser.parse_args()
    platform_target = options.platform_target

    package_root = REPO_ROOT
    if options.from_package:
        archive_path = os.path.join(
            REPO_ROOT, KIT_ARCHIVE_PATTERN.format(config=options.config)
        )
        package_root, _ = omni.repo.man.find_and_extract_package(archive_path, options.clean)

    # Route to appropriate builder based on requested products
    if "coreapi" in options.product:
        build_coreapi_packages(package_root, options)

    # Check if any kit-sdk pipeline products were requested
    if set(options.product) & set(KIT_SDK_PIPELINE):
        build_kit_sdk_packages(package_root, options)


if __name__ == "__main__":
    main()
